/**
 * @brief JUCE colour-id to CSS variable-name map.
 *
 * Maps each JUCE component colour-id ordinal to the `--Component--…ColourId`
 * CSS custom-property name the theme resolves it to. The key is the JUCE
 * colour-id constant; the value is the variable name written into the
 * generated stylesheet and read back by the styling engine.
 */
